#include <cstdio>
#include <vector>
#include <algorithm>

int main() {
    int a, b, k;
    if (scanf("%d%d%d", &a, &b, &k) != 3) return 0;

    std::vector<bool> is_prime(b + 1, true);
    if (b >= 0) is_prime[0] = false;
    if (b >= 1) is_prime[1] = false;

    for (long long i = 2; i * i <= b; ++i) {
        if (is_prime[i]) {
            for (long long j = i * i; j <= b; j += i)
                is_prime[j] = false;
        }
    }

    std::vector<int> primes;
    for (int i = std::max(a, 2); i <= b; ++i) {
        if (is_prime[i]) primes.push_back(i);
    }

    if (static_cast<int>(primes.size()) < k) {
        printf("-1\n");
        return 0;
    }

    int answer = primes[k - 1] - a + 1;

    for (int i = 0; i + k < static_cast<int>(primes.size()); ++i)
        answer = std::max(answer, primes[i + k] - primes[i]);

    answer = std::max(answer, b - primes[primes.size() - k] + 1);

    printf("%d\n", answer);
    return 0;
}

