    std::vector<bool> is_prime(b + 1, true);
    if (b >= 0) is_prime[0] = false;
    if (b >= 1) is_prime[1] = false;

    for (int i = 2; 1LL * i * i <= b; ++i) {
        if (is_prime[i]) {
            for (long long j = 1LL * i * i; j <= b; j += i)
                is_prime[static_cast<int>(j)] = false;
        }
    }

    std::vector<int> prime_cnt(b + 1, 0);
    for (int i = 1; i <= b; ++i)
        prime_cnt[i] = prime_cnt[i - 1] + (is_prime[i] ? 1 : 0);

    if (prime_cnt[b] - prime_cnt[a - 1] < k) {
        printf("-1\n");
        return 0;
    }

    auto valid = [&](int length) {
        for (int left = a; left + length - 1 <= b; ++left) {
            int right = left + length - 1;
            if (prime_cnt[right] - prime_cnt[left - 1] < k)
                return false;
        }
        return true;
    };

    int low = 1, high = b - a + 1;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (valid(mid))
            high = mid;
        else
            low = mid + 1;
    }

    printf("%d\n", low);
    return 0;
}

